 /*masterMpSoBuyerOrderCreation_savingRow1    저장버튼 */

UPDATE KEPIVGR 
SET IV_DATE = #{IV_DATE},
	  DI_DATE = #{DI_DATE},
	  GR_DATE = #{GR_DATE}
WHERE BUYER = #{BUYER} AND PO_NO = #{PO_NO} AND PO_SEQ = #{PO_SEQ} AND AGENCY_USER_ID = #{KEP_USER_ID}


	 /*masterMpSoBuyerOrderCreation_saveGridtoDB    엑셀업로드시 인설트 */

INSERT INTO KEPIVGR (AGENCY_USER_ID, BUYER, PO_NO, PO_SEQ, IV_DATE, DI_DATE, GR_DATE, JOB_DATM	)	 		
VALUES( UPPER(#{KEP_USER_ID}) , UPPER(#{BUYER}) , UPPER(#{PO_NO}) , #{PO_SEQ},  #{IV_DATE}, #{DI_DATE},  #{GR_DATE} , sysdate )

