/*masterMpSoBuyerOrderCreation_buyerOrderQuery ? */
SELECT AP.KEP_USER_ID ,AP.BUYER ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = (SELECT BUYER FROM ICOMCMPY WHERE COM_CODE=AP.BUYER AND STATUS <> 'D')) AS BUYER_NAME ,AP.AGENT ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = (SELECT AGENT FROM ICOMCMPY WHERE COM_CODE=AP.AGENT AND STATUS <> 'D')) AS AGENT_NAME ,AP.BUYER_ITEM_NO ,AP.REF_PR_NO ,AP.UNIT_PRICE ,AP.LIST_PRICE ,AP.ITEM_QTY FROM KEP_AGENCY_PO AP WHERE AP.KEP_USER_ID = #{st_kep_user_id} AND NVL(AP.IF_FLAG,'N') = 'C'
AND AP.BUYER = #{st_buyer_code}
ORDER BY AP.KEP_USER_ID, AP.BUYER, AP.BUYER_ITEM_NO

/*masterMpSoBuyerOrderCreation_getUplodingCheck 업로딩결과 조회*/ SELECT A.AGENCY_USER_ID AS KEP_USER_ID ,A.BUYER ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BUYER ) AS BUYER_NAME_LOC ,A.PO_NO ,A.PO_SEQ ,DECODE(A.PROCESS_TYPE,'0','직납','1','재고','2','TR','3','VMI') AS PROCESS_TYPE ,A.IV_DATE ,A.DI_DATE ,A.GR_DATE ,DECODE(A.JOB_FLAG,'A','최초등록','E','검증오류','N','검증완료','X','생성오류',null) as JOB_FLAG ,A.JOB_MSG ,A.JOB_DATM ,(SELECT DECODE(NVL(MSDS_NO, 'X'), 'X', 'N', 'Y') FROM ICOMBYIT WHERE (BUYER, BUYER_ITEM_NO) IN (SELECT BYIT_COMORG_CODE, BUYER_ITEM_NO FROM ICOMPODT WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ) AND CMS_CATEG_ID IN (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'CM11' AND FLAG = 'Y')) AS MSDS_NO FROM KEPIVGR A WHERE A.AGENCY_USER_ID = #{st_kep_user_id}
AND A.JOB_FLAG IN ( 'E' , 'X' )
ORDER BY A.BUYER , A.PO_NO , A.PO_SEQ

